import{_ as t,a as o}from"./chunks/66c22362084b0b3b5a14.hSo_Xpn-.js";import{_ as a,o as r,c as i,a6 as n}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"How My Startup Made $759,900 In 6 Months (Without Launching)","description":"","frontmatter":{"title":"How My Startup Made $759,900 In 6 Months (Without Launching)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-my-startup-made-759900-in-6-months-without-launching.md","filePath":"en/letters/how-my-startup-made-759900-in-6-months-without-launching.md"}'),s={name:"en/letters/how-my-startup-made-759900-in-6-months-without-launching.md"};function p(u,e,l,h,d,c){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="how-my-startup-made-759-900-in-6-months-without-launching" tabindex="-1">How My Startup Made $759,900 In 6 Months (Without Launching) <a class="header-anchor" href="#how-my-startup-made-759-900-in-6-months-without-launching" aria-label="Permalink to &quot;How My Startup Made $759,900 In 6 Months (Without Launching)&quot;">​</a></h1><p>Dan Koe · 2024-04-20 · <a href="https://thedankoe.com/letters/how-my-startup-made-759900-in-6-months-without-launching/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-my-startup-made-759900-in-6-months-without-launching">返回中文译文</a></p><p>This past weekend, I visited my developer team in Toronto, Canada.</p><p>We are doing things a bit differently at <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>, and I want to get vulnerable with you.</p><p>I want to document building our startup in public so you can learn from our failures and successes (and trust me, we have plenty of failures already).</p><p>I want to talk about how we generated $759,900 in 6 months without launching to the public.</p><p>The problem is that most people dream of building a massive company, but most of them go about it wrong.</p><ul><li>They think they need startup capital.</li><li>They think they need investors and VC money.</li><li>They think they need to pour a bunch of money into marketing.</li><li>They build the product without thinking about how they will get users or if the idea is good to begin with.</li></ul><p>We took a completely different approach.</p><p>The good thing about our approach is that anyone can do it.</p><p>The bad thing about our approach is that it takes time.</p><p>When I landed in Toronto, I wanted to ask our core developers what their biggest lessons have been while building Kortex.</p><p>I wasn’t expecting the answers they gave.</p><p>I think you’ll benefit from what they had to say.</p><p>We will start there, then, I will tell you how to come up with a profitable startup idea and fund it without external help.</p><h2 id="imperfection-high-agency-people-and-building-from-scratch" tabindex="-1">Imperfection, High-Agency People, and Building From Scratch <a class="header-anchor" href="#imperfection-high-agency-people-and-building-from-scratch" aria-label="Permalink to &quot;Imperfection, High-Agency People, and Building From Scratch&quot;">​</a></h2><p>I’ll start with my biggest lesson.</p><p>I didn’t realize how complex and costly software development can be.</p><p>It’s just a note-taking app, right?</p><p>Wrong. We take so much of the software we use for granted. And we aren’t taking the cheap no-code route to deliver a crappy product to you.</p><p>We have a burn rate close to $30,000/week.</p><p>We’ve removed 3-4 major features already that took months of developer time and energy.</p><p>We’ve added major features we didn’t plan for.</p><p>We already have a V2 design of the app in the works.</p><p>Building the app has been a constant string of problems, and I wouldn’t have it any other way.</p><p>We have no idea what we’re doing because it’s impossible to guess what problem will pop up next.</p><p><strong>So, my biggest lesson is this:</strong></p><p>Be okay with doing things imperfectly.</p><p>Yes, our costs could be lower (if we didn’t recruit top talent). Yes, we could launch an MVP we aren’t proud of. Yes, we could do a lot of things, but boy are we gaining valuable life experience that will pay off 10-fold down the road.</p><p>Our mindset can change, but our goal isn’t acquisition right now. We want to build the app we want to see in the world. An app that will benefit people’s lives on a daily basis like it already does mine (seriously, I’m addicted to it).</p><p><strong>Lesson 2) The Importance Of Being A High-Agency Individual</strong></p><p><a href="https://player.vimeo.com/video/936299568?h=3bd8384e1a&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><p><strong>Lesson 3) Learning To Work With A Team As A Lone Wolf</strong></p><p><a href="https://player.vimeo.com/video/936299497?h=53dd4c4ba4&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><p><strong>Lesson 4) Building From Scratch Takes More Work Than Working At An Established Company</strong></p><p><a href="https://player.vimeo.com/video/936299451?h=9067a40768&amp;dnt=1&amp;app_id=122963" target="_blank" rel="noreferrer">观看原文视频</a></p><h2 id="the-importance-of-building-an-audience" tabindex="-1">The Importance Of Building An Audience <a class="header-anchor" href="#the-importance-of-building-an-audience" aria-label="Permalink to &quot;The Importance Of Building An Audience&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>Most people don’t even think of social media when they start a business.</p><p>They don’t see how it is the biggest “shortcut” to success.</p><p>We aren’t building a business in the 2000s. Technology has advanced. You don’t need to put in grueling hours with direct sales, cold outreach, and manually finding potential customers.</p><p>Social media is how you:</p><ul><li>Test ideas with content that turns into marketing and products that sell (without spending any money).</li><li>Build an audience of people who want to buy the product when you launch it (because most startups can’t get users).</li><li>Sell a low marginal cost digital product to get results and validate your startup idea before building it.</li><li>Recruit developers, a team, and investors if you want to go that route.</li></ul><p>Many people think I just write content to write content.</p><p>This is partially true, but I’ve written 40,000 tweets, posted 3000+ more to other platforms, sent hundreds of newsletters, and posted hundreds of YouTube videos.</p><p>Because of that, I have <em>data</em>.</p><p>I know exactly what ideas pull in followers, catch attention, spark controversy, lead to customers, and get engagement.</p><p>I have a database of ideas that I can use as products, inside my products, on my sales pages, and in my promotions. I don’t have to do any manual market research, and I don’t have to put time into building the product to test whether it will sell.</p><p>By writing and building an audience on social media, I get to skip the grind that most startups and businesses go through.</p><p>Here are a few simple steps to start:</p><h3 id="_1-create-your-topic-tree" tabindex="-1">1) Create Your Topic Tree <a class="header-anchor" href="#_1-create-your-topic-tree" aria-label="Permalink to &quot;1) Create Your Topic Tree&quot;">​</a></h3><p>Write down a list of all of your interests, skills, and ideas you want to talk about.</p><p>Don’t worry about getting specific, worry about getting relatable.</p><p>Don’t niche down too far just yet. Start broad and applicable to most people.</p><p>Examples of applicable topics are ones you see online all the time: productivity, self-improvement, health and fitness, social dynamics, skill acquisition, career advice, business, etc.</p><p>If your topic is “leadership for teams and executives” turn that into “self-improvement” or frame it in a way that can benefit more people (without stripping the potential to attract the specific audience you want).</p><p>You don’t have to call out teams and executives for them to resonate with content. Write for them, but in a way that others can benefit from, too.</p><p>Remember, this is social media. It’s not targeted. It’s random. You have to start broad and funnel people into your expertise.</p><p>If you have 100 followers, and your topics are niche, good luck getting your content in front of enough people.</p><p>You need a larger audience that can spread your name to <em>reach</em> the specific people you want. It doesn’t matter if your audience isn’t completely filled with potential buyers.</p><p>I’d rather have 100,000 people who can spread my name to specific people in their network rather than 1,000 people who know exactly what I do. Especially if I’m building a startup where I need all of the leverage, resources, and connections I can get.</p><p>By the way, if you want first access to Kortex, we are running a writing BootCamp limited to 500 people.</p><p>You get 1 year of access to Kortex as we teach you how to write on social media to build an audience for your business, work, or career.</p><p>The first Bootcamp starts May 13. <a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">Check it out here.</a></p><h3 id="_2-make-noise-focus-on-signal" tabindex="-1">2) Make Noise &amp; Focus On Signal <a class="header-anchor" href="#_2-make-noise-focus-on-signal" aria-label="Permalink to &quot;2) Make Noise &amp; Focus On Signal&quot;">​</a></h3><p>Now, just start writing.</p><p>Talk about your interests.</p><p>Talk about your opinions.</p><p>Talk about your expertise.</p><p>Talk about your beliefs.</p><p>Teach people the skills you have, the mindset required to see success in your field, and the benefits of doing what you teach.</p><p>The more you write, the more data points you have.</p><p>Emulate what works.</p><p>Build a swipe file of ideas you wish you wrote.</p><p>Study the structure of posts and threads that do well.</p><p>Literally have 10-20 of your favorite posts open next to you as you write.</p><p>Don’t try to write your ideas blindly. You need to write with readability, impact, and in a style that the platform is used to.</p><p>There’s a reason all creators talk about similar topics in a similar way… because it works. This changes occasionally and you need to flow with what the market wants.</p><p>From there, stick it out for 3-6 months.</p><p>Review all of your posts and see which ones did better.</p><p>Make those ideas a solidified part of your brand. Write about them more often because they will continue to do well. Include them in your marketing, promotions, and as ideas for products. People want more of that.</p><p>When you have enough validated ideas through content, you can move on to the next step.</p><h2 id="how-to-fund-your-startup" tabindex="-1">How To Fund Your Startup <a class="header-anchor" href="#how-to-fund-your-startup" aria-label="Permalink to &quot;How To Fund Your Startup&quot;">​</a></h2><p><img src="'+o+'" alt="You have everything you need to build what you want. It&#39;s 2024. If you have an internet connection, you can be free."></p><p>Finally, to answer your question, how did we make almost $800K in 6 months without launching the app yet?</p><p>It’s relatively simple, and it’s the same thing I’ve talked about in almost every one of my business newsletters.</p><p>We have a team of 9 developers building the Kortex app and 6 creators (including myself) building Kortex University – the side where we teach writing.</p><p>Our first priority with Kortex was to generate <em>cash flow</em> so we didn’t have to take on investors or continue to dig into our own money (I invested $500K of my own money as an initial safeguard to fuel development).</p><p>We built a digital product with ideas we’ve validated before.</p><p>We started building the Kortex social media and email list. Our X and Instagram accounts are almost at 10,000 followers each. Our email list is also closing in on 10,000 subscribers.</p><p>Digital products cost very little to build and distribute. I’ve built multiple under my own brand so I know how to do it fast.</p><p>In short, we built a program that teaches writing and fueled it with social media traffic.</p><p>But, I wouldn’t recommend doing it under your startup first. I would recommend doing it under your own brand, then, after building cashflow and having the skill to build a startup, you can repeat that same process under the startup’s brand.</p><p>Here are the steps to take:</p><h3 id="_1-write-content-build-a-program-do-client-work" tabindex="-1">1) Write Content, Build A Program, &amp; Do Client Work <a class="header-anchor" href="#_1-write-content-build-a-program-do-client-work" aria-label="Permalink to &quot;1) Write Content, Build A Program, &amp; Do Client Work&quot;">​</a></h3><p>You need cash flow.</p><p>When you start building your personal brand and testing ideas with content (as mentioned above), you’ll start to get a feel for what you can help people with.</p><p>Turn your expertise into a program that helps people do what you’ve done.</p><p>As a writer, I help people with writing.</p><p>As a health nut, you can help people with fitness.</p><p>As a productivity expert, you can help people become more productive.</p><p>Yes, you need to actually get good at something before you can help people with a business.</p><p>Your job is to build a curriculum and guide people through it 1 on 1 with weekly calls, worksheets, and tasks to get results.</p><p>When you don’t have a large audience, it doesn’t make sense to sell a product yet. You need to charge $1000-$5000+ per client.</p><p>I’ll talk about this process in a future letter soon.</p><h3 id="_2-get-results-grow-your-audience-productize-your-offer" tabindex="-1">2) Get Results, Grow Your Audience, &amp; Productize Your Offer <a class="header-anchor" href="#_2-get-results-grow-your-audience-productize-your-offer" aria-label="Permalink to &quot;2) Get Results, Grow Your Audience, &amp; Productize Your Offer&quot;">​</a></h3><p>As your audience grows, you have more leverage.</p><p>We discussed this progression in <a href="/letters/zero-to-1-million-as-a-one-person-business-while-working-2-4-hours-per-day">Zero To $1 Million As A One-Person Business.</a></p><p>In between these steps, it is your full time job to improve your program to get better results for your customers.</p><p>Work with them closely and study their problems.</p><p>Results are all that matter. Your results are what will lead to more customers and a profitable startup idea.</p><p>And, since you’ve built an audience around this, you don’t have to worry too much about getting initial users. Your clients, customers, and readers are enough validation for the startup idea that stems from building your own brand.</p><p>You have more traffic and potential customers in your audience, so it only makes sense to turn a part of your program into a course that more people can access.</p><p>You can do this in two ways:</p><ol><li><strong>A cohort-based course</strong> – you have a curriculum, community, and live calls to help guide groups of people through the program. You can charge more for this structure and launch a cohort every 1-3 months.</li><li><strong>A regular course</strong> – this is where you just sell the curriculum as a course. The upside is that it requires very little work on your end. The downsides is that you only launch once and charge a lower price.</li></ol><p>Under my brand, I’ve iterated on my products to the point where 2 Hour Writer is my best-selling course.</p><p>I have an audience of writers and creators that I’ve helped.</p><p>With close to 15,000 students in 2 Hour Writer alone, it makes sense to build a writing app with my system to help make their process better.</p><h3 id="_3-build-your-startup-repeat-the-process" tabindex="-1">3) Build Your Startup &amp; Repeat The Process <a class="header-anchor" href="#_3-build-your-startup-repeat-the-process" aria-label="Permalink to &quot;3) Build Your Startup &amp; Repeat The Process&quot;">​</a></h3><p>You now have:</p><ul><li>Thousands of social media posts to pull data from on what works.</li><li>Dozens of clients that you’ve personally helped get better at what you do.</li><li>Hundreds or thousands of students who can benefit from your startup idea.</li><li>A hyper-profitable digital product business with enough cash flow to start building your product and team for your startup.</li></ul><p>You solve the problem that most startups have:</p><p>They can build an okay product, but they can’t get users. Therefore they can’t make money. And they don’t have a cashflow generating business of their own that both validates their startup idea and allows them to fuel it’s growth.</p><p>At this point, repeat the process for your startup.</p><p>Build the social media accounts.</p><p>Start testing ideas with content related to your startup.</p><p>Build out your value ladder starting with client work.</p><p>Get results for those initial customers and productize further into a cohort or course.</p><p>Hire a team for both the development and education side of the brand so you can do it faster than before.</p><p>With all of this, we can still fail. Kortex could go absolutely nowhere, and we’re okay with that. All of this advice is subject to your skill, not luck.</p><p>I hope this was helpful in providing a big-picture roadmap for building your startup.</p><p>I’ll talk more about how we are building Kortex as it is built.</p><p>Thank you for reading and enjoy the rest of your weekend.</p><p>Dan</p>',134)])])}const g=a(s,[["render",p]]);export{y as __pageData,g as default};
